// Authored content for 3.1.11.1 Genetic diversity (OxfordAQA 9610 v5.1, printed p.20; statements 3.1.11.1.s1–s2 in
// data/spec.js). The specification lists three ways of measuring genetic diversity within or between species (base
// sequences of DNA or mRNA; frequencies of specific base sequences or alleles in populations; amino-acid sequences of
// encoded proteins) and asks students to interpret data on similarities and differences in base or amino-acid
// sequences to suggest relationships. All sequences are ILLUSTRATIVE (constructed for teaching; see _biodiv-art.js)
// and every count and percentage below is computed from them by B.biodivModel.compare and was checked by hand.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.biodivArt, M = window.BIO.biodivModel, SQ = M.SEQ;
  const R = "3.1.11.1";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const P = (slot) => window.BIO.views.photo(slot);
  const C = (a, b, o) => M.compare(a, b, o);
  const one = (x) => [M.fix(x, 1), M.fix(x, 2)]; // accepted answers for "to 1 decimal place" (the 2 d.p. value is also accepted)
  const aaDiff = (a, b) => { const x = M.translate(a), y = M.translate(b); return x.filter((c, i) => c.aa !== y[i].aa).length; };
  const pqAaN = M.translate(SQ.p).length, pqAaPct = (100 * (pqAaN - aaDiff(SQ.p, SQ.q))) / pqAaN; // Case 1 amino-acid similarity (6 of 8 = 75.0 %)
  const pq = C(SQ.p, SQ.q), syn = C(SQ.syn1, SQ.syn2), jkEx = C(SQ.j, SQ.kAligned), jkCt = C(SQ.j, SQ.kAligned, { gaps: "count" }), ef = C(SQ.e, SQ.fRna, { tu: true }), ghWrong = C(SQ.g, SQ.hReported), ghRight = C(SQ.g, SQ.hCoding), r1 = C(SQ.s1, SQ.t1), r2 = C(SQ.s2, SQ.t2);
  const MX = M.matrix(M.PROT), sp = M.PROT.map((x) => x.sp), mx = (a, b) => MX[sp.indexOf(a)][sp.indexOf(b)];
  const protTable = `<table class="tbl"><thead><tr><th>Species</th><th>Amino-acid sequence (positions 1–20, one-letter codes)</th></tr></thead><tbody>${M.PROT.map((p) => `<tr><th>${p.sp}</th><td style="font-family:ui-monospace,Menlo,Consolas,monospace;letter-spacing:.08em;word-break:break-all">${p.seq}</td></tr>`).join("")}</tbody></table>`;
  const mxTable = `<table class="tbl"><thead><tr><th></th>${sp.map((x) => `<th>${x}</th>`).join("")}</tr></thead><tbody>${sp.map((a) => `<tr><th>${a}</th>${sp.map((b) => `<td>${a === b ? "–" : mx(a, b).diff}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const mono = (s) => `<span style="font-family:ui-monospace,Menlo,Consolas,monospace;letter-spacing:.06em;word-break:break-all">${M.chunk(s, 3).join(" ")}</span>`;

  // Sanity checks on the illustrative data: the page text below quotes these values.
  const expect = (cond, msg) => { if (!cond) console.warn("3.1.11.1 data check failed:", msg); };
  expect(pq.subs === 4 && aaDiff(SQ.p, SQ.q) === 2 && syn.subs === 5 && aaDiff(SQ.syn1, SQ.syn2) === 0 && jkEx.identical === 29 && jkEx.compared === 30 && jkCt.denom === 33 && ef.subs === 4 && ghRight.subs === 2 && r1.subs === 1 && r2.subs === 8, "sequence counts");
  expect(mx("V", "W").diff === 1 && mx("V", "X").diff === 3 && mx("V", "Y").diff === 5 && mx("X", "Y").diff === 8 && mx("V", "Z").diff === 8, "protein matrix");

  // ---- Sequence Comparison Laboratory cases (data for js/views/interactives-biodiv.js, kind bdvSeqLab) ----
  const cases = [
    { id: "subs", label: "1. Count substitutions", title: "Case 1. A gene region in species P and Q", intro: "Both sequences are the DNA coding strand of the same gene, written 5′→3′ and already aligned. Find the substitutions, count them and calculate the percentage similarity. Then translate both sequences to see how many amino acids differ. Notice that the amino-acid percentage similarity comes out lower than the DNA percentage, even though fewer amino acids than bases differ.", a: { name: "Species P", seq: SQ.p, type: "DNA coding strand" }, b: { name: "Species Q", seq: SQ.q, type: "DNA coding strand" }, translate: true,
      questions: [{ id: `q-${R}-sl1`, ref: R, stmts: S(2), type: "gap", marks: 3, stem: "Case 1. Use the laboratory to compare the two sequences. Give the percentage similarity to 1 decimal place.", text: "Number of base substitutions: {{1}}. Percentage similarity of the DNA: {{2}} %. Number of amino acids that differ: {{3}}.", answers: { 1: [String(pq.subs)], 2: one(pq.pct), 3: [String(aaDiff(SQ.p, SQ.q))] }, explanation: `${pq.identical} of ${pq.length} bases are identical: ${pq.identical} ÷ ${pq.length} × 100 = ${M.fix(pq.pct, 1)} %. Two of the four substitutions (AAA → AAG, both lysine; TGC → TGT, both cysteine) do not change the amino acid; the other two do (Val → Ile, Gly → Ala). So the protein shows fewer differences (2 against 4) but a lower percentage similarity (${M.fix(pqAaPct, 1)} %, ${pqAaN - aaDiff(SQ.p, SQ.q)} of ${pqAaN} amino acids, against ${M.fix(pq.pct, 1)} % for 24 bases): a percentage similarity depends on what is compared.` }] },
    { id: "syn", label: "2. Same protein, different DNA", title: "Case 2. Differences that do not change the protein", intro: "The coding strands of one gene in two species. Count the differences, then translate both. This case shows why comparing DNA can reveal differences that comparing amino-acid sequences would miss.", a: { name: "Species 1", seq: SQ.syn1, type: "DNA coding strand" }, b: { name: "Species 2", seq: SQ.syn2, type: "DNA coding strand" }, translate: true,
      questions: [{ id: `q-${R}-sl2`, ref: R, stmts: S(1, 2), type: "gap", marks: 2, stem: "Case 2. Give each answer to 1 decimal place.", text: "Percentage similarity of the DNA base sequences: {{1}} %. Percentage similarity of the amino-acid sequences: {{2}} %.", answers: { 1: one(syn.pct), 2: ["100", "100.0"] }, explanation: `${syn.identical} ÷ ${syn.length} × 100 = ${M.fix(syn.pct, 1)} % for the DNA, but every difference is in the third base of a codon and gives another codon for the same amino acid, so the amino-acid sequences are identical (100 %). The genetic code is degenerate.` },
        { id: `q-${R}-sl3`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Case 2. What can you conclude from the two comparisons?", options: ["Comparing DNA detected genetic differences that comparing the protein could not detect", "The two species have identical genes", "The DNA must have been sequenced wrongly, because the proteins are identical", "Amino-acid comparisons are always more reliable than DNA comparisons"], answer: 0, explanation: "Different codons can code for the same amino acid, so DNA can differ while the amino-acid sequence stays the same." }] },
    { id: "prot", label: "3. Five proteins", title: "Case 3. One protein region in five species", intro: "Amino-acid sequences (one-letter codes) of the same 20-residue region of one protein in species V to Z. Choose any two species to compare. Use the full table of differences to suggest how the species are related.", multi: M.PROT.map((p) => ({ name: `Species ${p.sp}`, seq: p.seq, type: "amino-acid sequence" })), pair: [0, 1],
      questions: [{ id: `q-${R}-sl4`, ref: R, stmts: S(2), type: "gap", marks: 2, stem: "Case 3. Give each answer as a whole number.", text: "Percentage similarity of species V and Y: {{1}} %. Percentage similarity of species X and Z: {{2}} %.", answers: { 1: [M.fix(mx("V", "Y").pct, 0)], 2: [M.fix(mx("X", "Z").pct, 0)] }, explanation: `V and Y differ at ${mx("V", "Y").diff} of 20 positions: 15 ÷ 20 × 100 = ${M.fix(mx("V", "Y").pct, 0)} %. X and Z differ at ${mx("X", "Z").diff}: 9 ÷ 20 × 100 = ${M.fix(mx("X", "Z").pct, 0)} %.` },
        { id: `q-${R}-sl5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Case 3. Which species is most closely related to species X, according to these data?", options: ["Species V", "Species W", "Species Y", "Species Z"], answer: 0, explanation: `X differs from V at ${mx("X", "V").diff} positions, from W at ${mx("X", "W").diff}, from Y at ${mx("X", "Y").diff} and from Z at ${mx("X", "Z").diff}. Fewest differences suggests the most recent common ancestor, though one short region is limited evidence.` }] },
    { id: "gaps", label: "4. A deletion: gaps", title: "Case 4. Sequences of different lengths", intro: "Species K's sequence is three bases shorter than species J's. Compare them first without aligning, to see why that is wrong, then align them. The aligned version has a gap of three positions (one codon missing in K). Switch between the two gap conventions.", a: { name: "Species J", seq: SQ.j, type: "DNA coding strand" }, b: { name: "Species K", seq: SQ.k, type: "DNA coding strand" }, aligned: SQ.kAligned, translate: true,
      questions: [{ id: `q-${R}-sl6`, ref: R, stmts: S(2), type: "gap", marks: 2, stem: "Case 4. After aligning, give each percentage similarity to 1 decimal place.", text: "With gap positions excluded from the comparison: {{1}} %. With each gap position counted as a difference: {{2}} %.", answers: { 1: one(jkEx.pct), 2: one(jkCt.pct) }, explanation: `${jkEx.identical} identical positions. Excluding the ${jkEx.gapCols} gap positions: ${jkEx.identical} ÷ ${jkEx.compared} × 100 = ${M.fix(jkEx.pct, 1)} %. Counting them as differences: ${jkEx.identical} ÷ ${jkEx.length} × 100 = ${M.fix(jkCt.pct, 1)} %. Always say which convention you used.` },
        { id: `q-${R}-sl7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Case 4. Comparing the unaligned sequences position by position gives a much lower similarity. Why?", options: ["After the missing bases, every base in K is compared with the wrong base in J", "Shorter sequences always have fewer identical bases", "The deletion changes every base after it", "Gaps are counted twice"], answer: 0, explanation: "A deletion shifts every later base of K by three places, so unaligned comparison pairs non-equivalent positions. Alignment restores the correspondence." }] },
    { id: "mrna", label: "5. mRNA v DNA", title: "Case 5. Comparing mRNA with a DNA coding strand", intro: "Species E's sequence is the DNA coding strand; species F's is mRNA. Both are written 5′→3′. The laboratory treats U in the mRNA as equivalent to T in the coding strand, because mRNA has the same base sequence as the coding strand except that U replaces T.", a: { name: "Species E (DNA)", seq: SQ.e, type: "DNA coding strand" }, b: { name: "Species F (mRNA)", seq: SQ.fRna, type: "mRNA" }, tu: true, translate: true,
      questions: [{ id: `q-${R}-sl8`, ref: R, stmts: S(1, 2), type: "gap", marks: 2, stem: "Case 5. Give the percentage to 1 decimal place.", text: "Number of base differences: {{1}}. Percentage similarity: {{2}} %.", answers: { 1: [String(ef.subs)], 2: one(ef.pct) }, explanation: `T and U at the same position are not differences. ${ef.subs} real differences: ${ef.identical} ÷ ${ef.length} × 100 = ${M.fix(ef.pct, 1)} %. Only the last codon change (UAU → UGU) alters the amino acid (Tyr → Cys).` }] },
    { id: "rc", label: "6. Wrong strand", title: "Case 6. A sequence reported for the other strand", intro: "Species H's sequence was reported for the complementary strand, written 5′→3′ (for example, because the other strand was the one sequenced). Compared directly with species G's coding strand it looks very different. The laboratory flags this: convert H's sequence to its reverse complement before comparing.", a: { name: "Species G", seq: SQ.g, type: "DNA coding strand" }, b: { name: "Species H (as reported)", seq: SQ.hReported, type: "complementary strand, 5′→3′" }, rc: true, translate: true,
      questions: [{ id: `q-${R}-sl9`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Case 6. Convert species H's sequence to the coding strand, then compare. Give the answer to 1 decimal place.", text: "Percentage similarity of G and H after conversion: {{1}} %.", answers: { 1: one(ghRight.pct) }, explanation: `After reverse complementing, ${ghRight.identical} of ${ghRight.length} bases match: ${M.fix(ghRight.pct, 1)} %. The direct comparison (${M.fix(ghWrong.pct, 1)} %) was meaningless because it compared non-equivalent bases from different strands.` },
        { id: `q-${R}-sl10`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Case 6. Why must H's sequence be reverse complemented, not just complemented?", options: ["The complementary strand runs antiparallel, so written 5′→3′ it is in the opposite order to the coding strand", "Complementing alone changes A to U", "Reverse complementing removes the mutations", "The sequence was too short"], answer: 0, explanation: "The two strands are antiparallel. Complementing gives the coding strand written 3′→5′; reversing it puts it 5′→3′, the same direction as G's sequence." }] },
    { id: "region", label: "7. Region matters", title: "Case 7. Two regions, two answers", intro: "Two regions of DNA from the same two species: a region inside a gene coding for an essential protein, and a non-coding region nearby. Compare each.", regions: [{ name: "Coding region", a: { name: "Species S", seq: SQ.s1, type: "DNA coding strand" }, b: { name: "Species T", seq: SQ.t1, type: "DNA coding strand" } }, { name: "Non-coding region", a: { name: "Species S", seq: SQ.s2, type: "DNA, non-coding" }, b: { name: "Species T", seq: SQ.t2, type: "DNA, non-coding" } }],
      questions: [{ id: `q-${R}-sl11`, ref: R, stmts: S(2), type: "gap", marks: 2, stem: "Case 7. Give each percentage to 1 decimal place.", text: "Coding region: {{1}} %. Non-coding region: {{2}} %.", answers: { 1: one(r1.pct), 2: one(r2.pct) }, explanation: `Coding region: ${r1.identical} ÷ 30 × 100 = ${M.fix(r1.pct, 1)} %. Non-coding region: ${r2.identical} ÷ 30 × 100 = ${M.fix(r2.pct, 1)} %. The same pair of species gives different percentages depending on the region compared.` },
        { id: `q-${R}-sl12`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Case 7. Which conclusion is justified?", options: ["A percentage similarity applies only to the region compared; it is not a single fixed measure of how related two species are", "The species are 96.7 % related, because the coding region is the more important of the two regions", "The non-coding result must be a sequencing error, because the same two species were compared", "Non-coding DNA cannot be used to study relationships, because it is not translated into protein"], answer: 0, explanation: "Regions under strong selection (essential coding sequences) usually change less than regions where changes have little effect, so percentages differ. Compare the same region across all species." }] },
  ];

  window.BIO.content[R] = {
    status: "draft",
    banner: "gel-sequencing", bannerText: "Every individual carries a slightly different set of DNA sequences. Comparing those sequences, within a species or between species, is how biologists measure genetic diversity and suggest how organisms are related.",
    keywords: ["genetic diversity", "base sequence", "DNA sequencing", "mRNA", "coding strand", "template strand", "allele", "allele frequency", "amino-acid sequence", "protein", "percentage similarity", "alignment", "gap", "substitution", "degenerate code", "evolutionary relationship", "common ancestor", "within species", "between species", "reverse complement"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.1.11.1).</strong> Genetic diversity within, or between, species can be measured by comparing: (1) the <strong>base sequence of DNA or of mRNA</strong>; (2) the <strong>frequency of specific base sequences or alleles in populations</strong>; (3) the <strong>amino-acid sequence of encoded proteins</strong>. You should be able to <strong>interpret data</strong> on similarities and differences in base sequences of DNA or in amino-acid sequences <strong>to suggest relationships</strong> between different organisms. <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">extension</span></div>

<h2 data-stmt="${R}.s1">1. What genetic diversity means <span class="badge teal">required</span></h2>
<p><span class="badge">supporting</span> <strong>Genetic diversity</strong> is the variety of alleles and DNA sequences present. Within a species it is often described as the number of different alleles of genes in a population, and how evenly they are represented. Between species it is the extent to which their DNA, and the proteins it codes for, differ.</p>
<ul><li><strong>Within a species:</strong> compare individuals or populations of the same species, for example two populations of a fish in different gulfs, or a wild and a farmed population of a crop plant.</li>
<li><strong>Between species:</strong> compare the same gene, or the same protein, in different species. The more similar the sequences, the more closely related the species are likely to be (section 5).</li></ul>
<p>The differences arise because DNA sequences change by mutation, and new combinations of alleles arise in meiosis and fertilisation (3.1.9). Over generations, populations that do not interbreed accumulate different changes.</p>
<div class="figure"><div class="fig-view">${A.measures()}</div></div>

<h2 data-stmt="${R}.s1 ${R}.s2">2. Comparing base sequences of DNA or mRNA <span class="badge teal">required</span></h2>
<p>DNA sequencing gives the order of bases in a gene or region. To compare two sequences:</p>
<ol><li><strong>Use equivalent sequences:</strong> the same gene or region, from the same strand, both written in the same direction (by convention 5′→3′).</li>
<li><strong>Align them</strong> so that equivalent positions are side by side. If one sequence has extra or missing bases (an insertion or a deletion), a <strong>gap</strong> (shown as –) is inserted so that the rest still lines up.</li>
<li><strong>Count</strong> the positions compared and the positions where the bases are identical. A position with different bases is a <strong>substitution</strong>.</li>
<li><strong>Percentage similarity</strong> = identical positions ÷ positions compared × 100.</li></ol>
<div class="figure"><div class="fig-view">${A.alignFig(SQ.p, SQ.q, { labels: ["species P", "species Q"], codons: true, aria: "two aligned 24-base DNA sequences with four substitutions marked" })}</div></div>
<div class="notice"><strong>Worked example.</strong> Species P and Q (above): 24 aligned positions, ${pq.subs} substitutions, so ${pq.identical} identical. Percentage similarity = ${pq.identical} ÷ 24 × 100 = <strong>${M.fix(pq.pct, 1)} %</strong> (1 decimal place). Percentage difference = 100 − ${M.fix(pq.pct, 1)} = ${M.fix(100 - pq.pct, 1)} %.</div>
<p><strong>mRNA.</strong> The base sequence of mRNA is the same as that of the DNA <strong>coding strand</strong>, except that mRNA contains <strong>uracil (U) in place of thymine (T)</strong> (3.1.8.2). So mRNA from one organism can be compared with mRNA from another, or with the coding strand of DNA, treating U and T at the same position as matching. Do not compare mRNA with the template strand: that is complementary to it. <span class="badge">supporting</span> mRNA comes only from genes that were being transcribed in the cells sampled.</p>
<p><strong>Gaps: state your convention.</strong> When a gap is present, there are two common ways to count:</p>
<ul><li><strong>Exclude gap positions</strong> from the denominator (compare only positions where both sequences have a base). This platform uses this convention unless a question says otherwise, and always reports the number of gap positions separately.</li>
<li><strong>Count each gap position as a difference</strong>, keeping it in the denominator.</li></ul>
<div class="figure"><div class="fig-view">${A.alignFig(SQ.j, SQ.kAligned, { labels: ["species J", "species K"], codons: true, aria: "two aligned DNA sequences, 33 positions, with a three-position gap in the second sequence and one substitution" })}</div></div>
<p>For J and K: ${jkEx.identical} identical positions, ${jkEx.subs} substitution and ${jkEx.gapCols} gap positions. Excluding gaps: ${jkEx.identical} ÷ ${jkEx.compared} × 100 = ${M.fix(jkEx.pct, 1)} %. Counting gaps as differences: ${jkEx.identical} ÷ ${jkEx.length} × 100 = ${M.fix(jkCt.pct, 1)} %. Both are correct calculations; they answer slightly different questions, so the convention must be stated. Comparing J and K <em>without</em> aligning them would pair every base after the deletion with the wrong base, giving a meaningless ${M.fix(M.naive(SQ.j, SQ.k).pct, 1)} % over the first 30 positions.</p>
<p><span class="badge">supporting</span> <strong>Direction and strand.</strong> The two strands of DNA are antiparallel. A sequence reported for the complementary strand and written 5′→3′ must be <strong>reverse complemented</strong> (complement each base, then reverse the order) before it is compared with a coding-strand sequence. Comparing it directly gives a misleadingly low similarity (Case 6 of the laboratory).</p>

<h2 data-stmt="${R}.s1">3. Comparing the frequency of specific base sequences or alleles in populations <span class="badge teal">required</span></h2>
<p>Within a species, individuals share the same genes but may carry different <strong>alleles</strong> (different base sequences of the same gene). Genetic diversity of a population can be measured by finding <strong>which alleles are present and how frequent each one is</strong>, or how often a particular base sequence occurs.</p>
<ul><li><strong>Allele frequency</strong> = number of copies of that allele ÷ total number of copies of the gene in the population. In a diploid organism each individual carries two copies of each gene (on autosomes).</li>
<li>A population with <strong>more alleles</strong>, at <strong>more even frequencies</strong>, has greater genetic diversity. A population in which one allele is very common and others are rare or absent has less.</li>
<li>Comparing frequencies between populations shows how different they are genetically, within the same species.</li></ul>
<div class="notice"><strong>Worked example.</strong> In a sample of 50 diploid plants, 30 are AA, 15 are Aa and 5 are aa. Copies of a = 15 + (2 × 5) = 25; total copies = 2 × 50 = 100. Frequency of a = 25 ÷ 100 = <strong>0.25</strong>; frequency of A = 75 ÷ 100 = <strong>0.75</strong>. The frequencies add up to 1.</div>
<div class="figure"><div class="fig-view">${A.alleleFig()}</div></div>
<p>In the chart, populations 1 and 2 carry four alleles at similar frequencies: they are genetically diverse and similar to each other. Population 3, small and isolated, carries only two alleles, one at a frequency of 0.85: its genetic diversity is lower. <span class="badge">supporting</span> Small populations tend to lose alleles by chance (genetic drift, studied at A-level).</p>

<h2 data-stmt="${R}.s1 ${R}.s2">4. Comparing amino-acid sequences of encoded proteins <span class="badge teal">required</span></h2>
<p>The amino-acid sequence of a protein is determined by the base sequence of the gene that codes for it (3.1.8). So differences in the amino-acid sequence of the same protein in different organisms reflect differences in their DNA. Proteins can be sequenced directly, or their amino-acid sequence can be worked out from the gene's base sequence.</p>
<p><strong>Comparing proteins can miss genetic differences.</strong> The genetic code is <strong>degenerate</strong>: most amino acids are coded for by more than one codon. A base substitution that turns one codon into another codon for the <strong>same</strong> amino acid changes the DNA but not the protein. A substitution can also change one amino acid for another.</p>
<div class="figure"><div class="fig-view">${A.synonymousFig()}</div></div>
<p>In the example above the DNA differs at ${syn.subs} of ${syn.length} positions (${M.fix(syn.pct, 1)} % similar) while the amino-acid sequences are 100 % identical. In species P and Q (section 2), ${pq.subs} base differences produced only ${aaDiff(SQ.p, SQ.q)} amino-acid differences. Counted as a number of differences, base sequences therefore always reveal <strong>at least as many</strong> differences as the amino-acid sequences they code for, and often more, because every amino-acid difference needs at least one base difference. <strong>A percentage can behave differently.</strong> For P and Q the DNA is ${M.fix(pq.pct, 1)} % similar (${pq.identical} of ${pq.length} bases) but the amino-acid sequence only ${M.fix(pqAaPct, 1)} % (${pqAaN - aaDiff(SQ.p, SQ.q)} of ${pqAaN} amino acids): one base change can alter a whole amino acid, and there are only a third as many amino acids as bases, so each amino-acid difference is a bigger share of the total. A percentage similarity depends on what is compared, so compare like with like.</p>
<p><span class="badge">supporting</span> <strong>A classic example.</strong> The protein cytochrome c (used in respiration in almost all eukaryotes) has been sequenced in many species; the human and chimpanzee sequences are identical, while more distantly related species show more differences. Identical proteins do not mean identical genes: the genes can still differ at bases that do not change the amino acids.</p>

<h2 data-stmt="${R}.s2">5. Interpreting sequence data to suggest relationships <span class="badge teal">required</span></h2>
<p>Organisms whose sequences are <strong>more similar</strong> (fewer differences, higher percentage similarity) are likely to share a <strong>more recent common ancestor</strong>, because there has been less time, since their lineages separated, for differences to accumulate. Organisms with <strong>more differences</strong> are likely to be <strong>less closely related</strong>.</p>
<p>The table gives the same 20-residue region of one protein in five species (illustrative sequences) and the number of positions at which each pair differs.</p>
${protTable}
<div class="figure"><div class="fig-view">${A.treeFig()}</div></div>
<ol><li><strong>Find the most similar pair:</strong> V and W differ at only ${mx("V", "W").diff} position (${M.fix(mx("V", "W").pct, 0)} % similar), so they are suggested to be the most closely related.</li>
<li><strong>Find what joins next:</strong> X differs from V at ${mx("V", "X").diff} and from W at ${mx("W", "X").diff}, fewer than from Y (${mx("X", "Y").diff}) or Z (${mx("X", "Z").diff}), so X is next most closely related to V and W.</li>
<li><strong>Continue:</strong> Y is closer to V and W (${mx("V", "Y").diff} and ${mx("W", "Y").diff}) than Z is (${mx("V", "Z").diff} and ${mx("W", "Z").diff}); Z differs most from every other species, so it is suggested to be the least closely related.</li></ol>
<p>Use cautious wording: the data <strong>suggest</strong> or <strong>support</strong> a relationship; they do not prove it.</p>

<h2 data-stmt="${R}.s2">6. Limits: what a percentage similarity does and does not tell you <span class="badge teal">required</span></h2>
<ul><li><strong>It depends on the region compared.</strong> Essential coding regions often change little; non-coding regions may change more. For species S and T the coding region is ${M.fix(r1.pct, 1)} % similar but a nearby non-coding region only ${M.fix(r2.pct, 1)} %. Compare the same region in every species, and prefer several genes or whole genomes.</li>
<li><strong>It depends on alignment and gaps.</strong> Unaligned sequences give meaningless results; the gap convention changes the value (section 2).</li>
<li><strong>DNA and protein comparisons can disagree,</strong> because of the degenerate code (section 4).</li>
<li><strong>It is evidence, not an exact measure of time since divergence.</strong> Different genes, and different lineages, change at different rates, and a later change can reverse or repeat an earlier one at the same position. A percentage similarity is not a universal measure of evolutionary distance. <span class="badge">supporting</span> Estimating dates from sequence differences ("molecular clocks") needs calibration, for example with fossils.</li>
<li><strong>Sample size.</strong> One individual may not represent its species; genetic diversity within each species means several individuals should be sequenced.</li></ul>

<h2 data-stmt="${R}.s1">7. Before sequencing <span class="badge">supporting</span></h2>
<p>Before DNA and protein sequencing were possible, genetic diversity was inferred from <strong>observable characteristics</strong>, many of which are affected by the environment as well as by genes (3.1.6). Sequence comparisons measure genetic differences more directly. Immunological comparisons of proteins and genome sequencing in classification are covered in 3.1.10.2.</p>
${P("gel-sequencing")}`,
    diagrams: [
      { id: "d-3.1.11.1-1", title: "Three ways to measure genetic diversity", status: "reviewed", caption: "The three measures named in the specification: comparing base sequences of DNA or mRNA; comparing the frequency of specific base sequences or alleles in populations; comparing amino-acid sequences of encoded proteins. Illustrative data.", alt: "Three panels. Left: two nine-base DNA sequences, ATGGCTAAA and ATGGCAAAA, aligned with the one differing base highlighted; 8 of 9 identical, 88.9 per cent. Centre: bar chart of three alleles in two populations: population P with frequencies 0.5, 0.3, 0.2; population Q with 0.9, 0.1 and 0. Right: two chains of five amino acids, Met Ala Lys Gly Leu and Met Ala Arg Gly Leu, with the third differing.", svg: A.measures() },
      { id: "d-3.1.11.1-2", title: "Comparing two aligned DNA sequences", status: "reviewed", caption: `Species P and Q, coding strand, 5′→3′ (illustrative). Substitutions are coloured and marked ×; dotted lines separate codons. ${pq.identical} of ${pq.length} positions are identical: ${M.fix(pq.pct, 1)} % similarity.`, alt: `Two 24-base sequences aligned one above the other. Positions 6, 10, 18 and 23 differ and are marked with a cross. Text below: 24 positions, 20 identical, 4 substitutions; percentage similarity 20 divided by 24 times 100 equals 83.3 per cent.`, svg: A.alignFig(SQ.p, SQ.q, { labels: ["species P", "species Q"], codons: true }) },
      { id: "d-3.1.11.1-3", title: "Gaps after a deletion", status: "reviewed", caption: `Species K lacks three bases present in J, so a gap of three positions is inserted to keep the rest aligned. Excluding gaps: ${M.fix(jkEx.pct, 1)} %; counting gap positions as differences: ${M.fix(jkCt.pct, 1)} %. State which convention you use.`, alt: "Two DNA sequences of 33 aligned positions. The second has dashes at positions 16 to 18 and one substitution near the end. Text below gives 29 identical, 1 substitution and 3 gap positions, and both percentages.", svg: A.alignFig(SQ.j, SQ.kAligned, { labels: ["species J", "species K"], codons: true }) },
      { id: "d-3.1.11.1-4", title: "Different DNA, same protein", status: "reviewed", caption: `Ten codons from two species. The ${syn.subs} differences are all third-position changes to another codon for the same amino acid, so the DNA is ${M.fix(syn.pct, 1)} % similar but the amino-acid sequence is 100 % identical. The genetic code is degenerate.`, alt: "Ten codon boxes for each species with the amino acid beneath each. Five boxes are highlighted where the third base differs, for example GCT and GCA, both alanine. The amino acids are the same in both rows: Met Ala Lys Gly Leu Pro Glu Ser Val Trp.", svg: A.synonymousFig() },
      { id: "d-3.1.11.1-5", title: "From a table of differences to suggested relationships", status: "reviewed", caption: "Number of amino-acid differences between five species in a 20-residue region (illustrative). V and W differ least; X joins them next, then Y; Z differs most from all. Branch lengths are not to scale, and one region is limited evidence.", alt: "A five-by-five table of differences: V–W 1, V–X 3, V–Y 5, V–Z 8, W–X 4, W–Y 6, W–Z 9, X–Y 8, X–Z 11, Y–Z 13. Beside it a branching diagram in which V and W join first, then X, then Y, then Z.", svg: A.treeFig() },
      { id: "d-3.1.11.1-6", title: "Allele frequencies in three populations", status: "reviewed", caption: "Frequencies of four alleles of one gene (illustrative). Populations 1 and 2 have four alleles at similar frequencies: high genetic diversity and similar to each other. Population 3 has two alleles, one at 0.85: lower genetic diversity.", alt: "Bar chart. Population 1: A1 0.45, A2 0.30, A3 0.15, A4 0.10. Population 2: 0.40, 0.35, 0.15, 0.10. Population 3: 0.85, 0.15, 0, 0.", svg: A.alleleFig() },
    ],
    interactives: [
      { kind: "bdvSeqLab", title: "Sequence Comparison Laboratory", note: "Compare aligned DNA, mRNA or amino-acid sequences (illustrative, constructed for teaching). Mark the positions you think differ, check your marking, then see the counts and the percentage similarity worked out. Seven cases cover substitutions, the degenerate code, a family of five proteins, gaps, mRNA, a sequence reported for the other strand and how the region compared changes the answer.", items: cases },
    ],
    focus: [
      { slot: "gel-sequencing", title: "Reading a DNA sequence", ref: R, explanation: () => `<p><span class="badge">supporting</span> Sequence comparisons start with sequencing. In the chain-termination method, DNA polymerase copies a single-stranded template many times, building complementary strands; each copy stops at the point where a modified (chain-terminating) nucleotide is added. This gives a set of fragments of every length, each ending in a known base; in modern machines each of the four terminating nucleotides carries a different fluorescent label. The fragments are separated by size (shortest fastest) by electrophoresis in a gel or a fine capillary, and the label at the end of each length is read in turn. Read from the shortest fragment to the longest, the labels give the base sequence of the new strand, 5′→3′, which is <strong>complementary</strong> to the template. On older slab gels, four separate reactions (one for each base) ran in four lanes and the sequence was read up the gel from the bottom; modern machines read coloured peaks on a trace. Newer methods read millions of fragments at once, so whole genomes can now be compared, but every read still has to be checked, aligned and compared on the same strand in the same direction before a percentage similarity means anything.</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "A research group sequences the same gene from two species of fish. The read for species A is the coding strand; the read for species B is of the complementary strand, written 5′→3′. Explain what the group must do before calculating a percentage similarity, and why. (3 marks)", scheme: [{ point: "Convert species B's read to the coding strand by reverse complementing it (complement each base and reverse the order)", marks: 1 }, { point: "Because the strands are complementary and antiparallel, so the reads are not equivalent sequences / direct comparison pairs non-equivalent bases", marks: 1 }, { point: "Then align the sequences (inserting gaps for insertions or deletions) before counting identical positions", marks: 1 }], model: "Species B's read is of the other strand, which is complementary to the coding strand and runs in the opposite direction. The group must complement each base and reverse the order to obtain B's coding strand written 5′→3′. Only then are the two sequences equivalent; they should then be aligned, with gaps inserted where one has an insertion or deletion, before identical positions are counted and the percentage similarity calculated.", commonErrors: "Complementing without reversing; comparing directly and concluding the species are distantly related." } },
    ],
    examFocus: `<ul><li>Name the three measures exactly: <strong>base sequence of DNA or mRNA</strong>; <strong>frequency of specific base sequences or alleles in populations</strong>; <strong>amino-acid sequence of encoded proteins</strong>.</li><li>Percentage similarity = identical positions ÷ positions compared × 100. Show the working and round as instructed. Percentage difference = 100 − similarity.</li><li>Compare like with like: the same gene or region, aligned, same strand, same direction (5′→3′). mRNA matches the <strong>coding</strong> strand with U for T.</li><li>Say which gap convention you use if gaps are present.</li><li>"More similar sequences suggest a more recent common ancestor / closer relationship." Use <em>suggest</em>, not <em>prove</em>.</li><li>Degenerate code: base differences may not change the amino-acid sequence, so DNA comparisons can show differences that protein comparisons miss.</li><li>A percentage similarity depends on the region compared and is not an exact measure of time since divergence.</li><li>Allele frequency: copies of the allele ÷ total copies (two per diploid individual).</li></ul>`,
    synoptic: [
      { ref: "3.1.7.1", text: "Complementary base pairing and antiparallel strands explain why sequences must be compared on the same strand, in the same direction." },
      { ref: "3.1.8.1", text: "The genetic code is degenerate, so some base substitutions do not change the amino-acid sequence." },
      { ref: "3.1.8.2", text: "mRNA has the base sequence of the coding strand with U in place of T." },
      { ref: "3.1.9.1", text: "Meiosis and random fertilisation produce new combinations of alleles: genetic diversity within a species." },
      { ref: "3.1.10.2", text: "Genome sequencing and immunology help to clarify taxonomic relationships." },
      { ref: "3.1.6", text: "Variation within and between species; observable characteristics are affected by genes and environment." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which of these is one of the ways the specification lists for measuring genetic diversity?", options: ["Comparing the frequency of specific alleles in populations", "Comparing the total mass of DNA in a cell", "Comparing the number of individuals of each species", "Comparing the heights of individuals"], answer: 0, explanation: "The three listed measures are base sequences of DNA or mRNA, frequencies of specific base sequences or alleles, and amino-acid sequences of encoded proteins." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Two aligned sequences of 40 bases differ at 6 positions. Give the answer as a whole number.", text: "Percentage similarity: {{1}} %.", answers: { 1: ["85"] }, explanation: "34 ÷ 40 × 100 = 85 %." },
      { id: `q-${R}-qc3`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Two species have identical amino-acid sequences for a protein. What can you conclude about the gene that codes for it?", options: ["Its base sequence may still differ between the species", "Its base sequence must be identical", "The two species are the same species", "The gene has no mutations in either species"], answer: 0, explanation: "The genetic code is degenerate: base substitutions can produce codons for the same amino acid." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Species F's sequence of a gene is 97 % similar to species G's and 82 % similar to species H's. The best conclusion is:", options: ["F is probably more closely related to G than to H", "F evolved from G", "H is not related to F", "The time since F and G diverged is exactly one sixth of the time since F and H diverged"], answer: 0, explanation: "Higher similarity suggests a more recent common ancestor; it does not show descent of one living species from another or give exact times." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "Three ways to measure genetic diversity (specification list).", back: "Compare: the base sequence of DNA or of mRNA; the frequency of specific base sequences or alleles in populations; the amino-acid sequence of encoded proteins." },
      { id: `f-${R}-2`, front: "Genetic diversity within a species v between species.", back: "Within: differences among individuals or populations of one species (e.g. allele frequencies). Between: differences in the same gene or protein in different species." },
      { id: `f-${R}-3`, front: "Percentage similarity of two aligned sequences.", back: "Identical positions ÷ positions compared × 100. Percentage difference = 100 − similarity." },
      { id: `f-${R}-4`, front: "Why must sequences be aligned before comparing?", back: "So equivalent positions are compared. An insertion or deletion would otherwise shift every later base; gaps (–) are inserted to restore the correspondence." },
      { id: `f-${R}-5`, front: "Two conventions for gaps in an alignment.", back: "Exclude gap positions from the denominator, or count each gap position as a difference. State which you use; this platform excludes them by default and reports gaps separately." },
      { id: `f-${R}-6`, front: "Which DNA strand is mRNA compared with?", back: "The coding strand: mRNA has the same base sequence with U in place of T." },
      { id: `f-${R}-7`, front: "A sequence of the complementary strand written 5′→3′: what must be done before comparing?", back: "Reverse complement it (complement every base, then reverse the order) to obtain the coding strand 5′→3′." },
      { id: `f-${R}-8`, front: "Allele frequency.", back: "Copies of the allele ÷ total copies of that gene in the population (two copies per diploid individual). Frequencies of all alleles add to 1." },
      { id: `f-${R}-9`, front: "Which population is more genetically diverse?", back: "The one with more alleles at more even frequencies. One very common allele with others rare or absent means lower diversity." },
      { id: `f-${R}-10`, front: "Why can amino-acid comparisons show fewer differences than DNA comparisons?", back: "The genetic code is degenerate: a base substitution may give another codon for the same amino acid, changing the DNA but not the protein." },
      { id: `f-${R}-11`, front: "What do more similar sequences suggest?", back: "A more recent common ancestor and a closer relationship (less time for differences to accumulate). Suggest, not prove." },
      { id: `f-${R}-12`, front: "Steps to interpret a table of sequence differences.", back: "Find the pair with fewest differences; then which species is next closest to that pair; continue until the most different species. Describe as suggested relationships." },
      { id: `f-${R}-13`, front: "Why is percentage similarity not an exact measure of time since divergence?", back: "Genes and lineages change at different rates; changes can recur at the same site; the value depends on the region, alignment and gap convention." },
      { id: `f-${R}-14`, front: "Why does the region compared matter?", back: "Essential coding regions often change slowly; non-coding regions may change faster. The same two species can give different percentages, so compare the same region in all species." },
      { id: `f-${R}-15`, front: "Why sequence several individuals of each species?", back: "There is genetic diversity within each species, so one individual may not represent the species." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which method would NOT, on its own, measure genetic diversity?", options: ["Comparing the base sequence of a gene in two species", "Comparing the frequency of an allele in two populations", "Comparing the amino-acid sequence of a protein in two species", "Comparing the total mass of DNA per cell in two species"], answer: 3, explanation: "The total mass of DNA says nothing about which sequences or alleles are present." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "A scientist compares mRNA from one species with DNA from another. With which DNA sequence should the mRNA be compared?", options: ["The coding strand, treating U as equivalent to T", "The template strand, treating U as equivalent to A", "Either strand, ignoring direction", "The amino-acid sequence of the protein"], answer: 0, explanation: "mRNA is complementary to the template strand, so it has the coding strand's sequence with U for T." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Why might comparing amino-acid sequences underestimate the genetic differences between two species?", options: ["Some base substitutions produce a codon for the same amino acid", "Proteins are made of more units than genes", "Amino acids mutate more slowly than bases", "Proteins cannot be sequenced accurately"], answer: 0, explanation: "Because the code is degenerate, some changes in DNA do not change the protein." },
      { id: `q-${R}-m4`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "In a population of 200 diploid animals there are 120 copies of allele B. What is the frequency of allele B?", options: ["0.30", "0.60", "0.12", "0.40"], answer: 0, explanation: "200 diploid individuals carry 400 copies of the gene: 120 ÷ 400 = 0.30." },
      { id: `q-${R}-m5`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Four populations of one plant species were tested for alleles of one gene. Which population is the most genetically diverse for this gene?", options: ["Four alleles at frequencies 0.25, 0.25, 0.25, 0.25", "Four alleles at frequencies 0.85, 0.05, 0.05, 0.05", "Two alleles at frequencies 0.5, 0.5", "One allele at a frequency of 1.0"], answer: 0, explanation: "Most alleles, most evenly represented." },
      { id: `q-${R}-m6`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Two aligned 50-base sequences differ at 4 positions. What is their percentage similarity?", options: ["92 %", "96 %", "8 %", "46 %"], answer: 0, explanation: "46 identical ÷ 50 × 100 = 92 %. 8 % is the percentage difference." },
      { id: `q-${R}-m7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "An alignment has 60 positions: 51 identical, 3 substitutions and 6 gap positions. Excluding gap positions, the percentage similarity is:", options: ["94.4 %", "85.0 %", "90.0 %", "95.0 %"], answer: 0, explanation: "Positions compared = 60 − 6 = 54; 51 ÷ 54 × 100 = 94.4 %. Counting gaps as differences would give 51 ÷ 60 × 100 = 85.0 %." },
      { id: `q-${R}-m8`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which statement about sequence data is most appropriate?", options: ["Fewer differences suggest a more recent common ancestor", "Fewer differences prove that one species evolved from the other", "The number of differences gives the exact time since two species diverged", "Any two species with more than 50 % similarity are the same species"], answer: 0, explanation: "Sequence data provide evidence that suggests relationships; they do not prove ancestry or give exact times." },
      { id: `q-${R}-m9`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "The same two species are 98 % similar for gene 1 and 85 % similar for gene 2. The best explanation is:", options: ["Different genes accumulate differences at different rates", "One of the sequences must have been read incorrectly", "The species are 91.5 % related", "Gene 2 cannot be used to study relationships"], answer: 0, explanation: "Percentage similarity depends on the region compared; genes under strong selection usually change less." },
      { id: `q-${R}-m10`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A student compares species A's coding strand with species B's sequence and gets 22 % similarity, far lower than expected for two related species. Which is the most likely error?", options: ["B's sequence is of the complementary strand and was not reverse complemented", "The student should have used more decimal places", "The sequences were too similar to compare", "Species B's DNA contains uracil"], answer: 0, explanation: "Comparing a coding strand with the other strand pairs non-equivalent bases and gives a meaninglessly low value." },
      { id: `q-${R}-m11`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Genetic diversity WITHIN a species could be measured by:", options: ["comparing the base sequence of a gene in many individuals of that species", "counting the number of species in a habitat", "comparing a gene in that species with the same gene in another species", "measuring the index of diversity of its community"], answer: 0, explanation: "Within-species diversity compares individuals or populations of the same species. Counting species and the index of diversity measure species diversity (3.1.11.2)." },
      { id: `q-${R}-m12`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: `Use the table of differences for species V to Z in the notes (V–W ${mx("V", "W").diff}, V–X ${mx("V", "X").diff}, V–Y ${mx("V", "Y").diff}, V–Z ${mx("V", "Z").diff}, X–Y ${mx("X", "Y").diff}, Y–Z ${mx("Y", "Z").diff}). Which species is suggested to be least closely related to V?`, options: ["Z", "Y", "X", "W"], answer: 0, explanation: `Z has the most differences from V (${mx("V", "Z").diff}) and from every other species.` },
      { id: `q-${R}-m13`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why should several individuals of each species be sequenced before species are compared?", options: ["There is genetic diversity within each species, so one individual may not be representative", "Sequencing machines need at least two samples", "Individuals of the same species always have identical sequences", "To increase the number of gap positions"], answer: 0, explanation: "Individuals of a species differ; several are needed for a representative comparison." },
      { id: `q-${R}-m14`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "A base substitution changes the codon GCU to GCC in one species. Both codons code for alanine. What is the effect on the comparison?", options: ["The DNA sequences differ at one base but the amino-acid sequences are identical", "Both the DNA and the amino-acid sequences differ at one position each", "Neither sequence differs, because the codon still codes for alanine", "The protein is shortened, because the new codon is read as a stop codon"], answer: 0, explanation: "A synonymous change: degenerate code." },
      // ---- gap ----
      { id: `q-${R}-g1`, ref: R, stmts: S(1), type: "gap", marks: 3, stem: "Complete the sentence from the specification.", text: "Genetic diversity can be measured by comparing the base sequence of {{1}} or of mRNA, the frequency of specific base sequences or {{2}} in populations, and the {{3}} sequence of encoded proteins.", answers: { 1: ["DNA"], 2: ["alleles", "allele"], 3: ["amino acid", "amino-acid", "aminoacid"] }, explanation: "DNA; alleles; amino-acid." },
      { id: `q-${R}-g2`, ref: R, stmts: S(2), type: "gap", marks: 2, stem: "Two aligned 60-base sequences have 9 substitutions and no gaps. Give answers to 1 decimal place.", text: "Percentage similarity: {{1}} %. Percentage difference: {{2}} %.", answers: { 1: ["85.0", "85"], 2: ["15.0", "15"] }, explanation: "51 ÷ 60 × 100 = 85.0 %; 100 − 85.0 = 15.0 %." },
      { id: `q-${R}-g3`, ref: R, stmts: S(1), type: "gap", marks: 2, stem: "A sample of 50 diploid plants contains 30 AA, 15 Aa and 5 aa. Give each answer to 2 decimal places.", text: "Frequency of allele a: {{1}}. Frequency of allele A: {{2}}.", answers: { 1: ["0.25"], 2: ["0.75"] }, explanation: "Copies of a = 15 + 2 × 5 = 25 of 100: 0.25. Copies of A = 2 × 30 + 15 = 75: 0.75." },
      { id: `q-${R}-g4`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "A protein of 104 amino acids differs between two species at 12 positions. Give the answer to 1 decimal place.", text: "Percentage similarity: {{1}} %.", answers: { 1: ["88.5", "88.46"] }, explanation: "92 ÷ 104 × 100 = 88.46… = 88.5 %." },
      // ---- matching ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(1), type: "match", marks: 4, stem: "Match each measure of genetic diversity to what is compared.", pairs: [{ left: "Base sequence of DNA", right: "The order of nucleotides in an aligned gene or region" }, { left: "Base sequence of mRNA", right: "Transcripts, matched to the DNA coding strand with U for T" }, { left: "Allele frequency", right: "The proportion of copies of each allele of a gene in a population" }, { left: "Amino-acid sequence", right: "The order of amino acids in a protein coded for by a gene" }] },
      { id: `q-${R}-mt2`, ref: R, stmts: S(2), type: "match", marks: 4, stem: "Match each observation to the best interpretation.", pairs: [{ left: "DNA differs at several bases; the protein is identical", right: "The substitutions give codons for the same amino acids" }, { left: "Species A and B differ at 2 positions; A and C at 15", right: "A is probably more closely related to B than to C" }, { left: "A coding region is 97 % similar; a non-coding region of the same species pair is 70 %", right: "The percentage depends on the region compared" }, { left: "One sequence is three bases shorter than the other", right: "An insertion or deletion: align the sequences with a gap" }] },
      // ---- sequence ----
      { id: `q-${R}-sq1`, ref: R, stmts: S(2), type: "sequence", marks: 5, stem: "Put these steps in order for calculating the percentage similarity of a gene in two species.", steps: ["Obtain the base sequence of the same gene from each species", "Make sure both are the same strand, written 5′→3′ (reverse complement one if necessary)", "Align the sequences, inserting gaps where bases are missing", "Count the positions compared (stating the gap convention) and the identical positions", "Divide identical positions by positions compared and multiply by 100"] },
      // ---- data, short answer and application ----
      { id: `q-${R}-s1`, ref: R, stmts: S(1), type: "short", marks: 3, stem: "Describe three ways in which genetic diversity within or between species can be measured. (3 marks)", scheme: [{ point: "Comparing the base sequence of DNA or of mRNA", marks: 1 }, { point: "Comparing the frequency of specific base sequences or alleles in populations", marks: 1 }, { point: "Comparing the amino-acid sequence of (the same) encoded protein", marks: 1 }], model: "By comparing the base sequences of DNA (or of mRNA) of the same gene or region; by comparing the frequencies of particular alleles, or of particular base sequences, in different populations; and by comparing the amino-acid sequence of the same protein in different organisms.", commonErrors: "Giving 'comparing observable characteristics' or 'counting species', which are not measures of genetic diversity in this specification." },
      { id: `q-${R}-s2`, ref: R, stmts: S(1, 2), type: "short", marks: 2, stem: "The gene for a protein differs at five bases between two species, but the amino-acid sequence of the protein is identical. Explain how this is possible. (2 marks)", scheme: [{ point: "The genetic code is degenerate: an amino acid can be coded for by more than one codon", marks: 1 }, { point: "The substitutions (e.g. in the third base) give a different codon for the same amino acid, so the amino-acid sequence is unchanged", marks: 1 }], model: "The genetic code is degenerate, so most amino acids are coded for by more than one codon. Each of the five substitutions has changed a codon into another codon for the same amino acid, often by changing its third base, so the protein's amino-acid sequence is unchanged.", commonErrors: "'The mutations were in introns' is possible in principle but does not use the degenerate code expected here; accept only as an additional point." },
      { id: `q-${R}-d1`, ref: R, stmts: S(2), type: "short", marks: 4, stem: `Data. The table shows the number of amino-acid differences in a 20-residue region of one protein in five species (illustrative).\n${mxTable}(a) Which two species are suggested to be most closely related? Explain. (1 mark) (b) Calculate the percentage similarity of species W and Y. (1 mark) (c) Explain why these data alone are not enough to establish how the five species are related. (2 marks)`, scheme: [{ point: `(a) V and W: fewest differences (${mx("V", "W").diff})`, marks: 1 }, { point: `(b) (20 − ${mx("W", "Y").diff}) ÷ 20 × 100 = ${M.fix(mx("W", "Y").pct, 0)} %`, marks: 1 }, { point: "(c) Only one short region of one protein: other genes or regions may give different results / change at different rates", marks: 1 }, { point: "(c) Degenerate code: DNA differences without amino-acid changes are not seen; or only one individual per species / similarity not an exact measure of divergence", marks: 1 }], model: `(a) V and W, which differ at only ${mx("V", "W").diff} position. (b) ${20 - mx("W", "Y").diff} ÷ 20 × 100 = ${M.fix(mx("W", "Y").pct, 0)} %. (c) The data cover only 20 amino acids of one protein; other proteins or genes may change at different rates and could suggest different relationships. Because the code is degenerate, base substitutions that do not change amino acids are invisible here, and with one individual per species the within-species diversity is unknown, so the data suggest relationships but do not establish them.`, commonErrors: "Giving the percentage difference (30 %) for (b); claiming the data 'prove' relationships." },
      { id: `q-${R}-s3`, ref: R, stmts: S(2), type: "short", marks: 3, stem: `Application. An alignment of the same gene from two species has ${jkEx.length} positions: ${jkEx.identical} identical, ${jkEx.subs} substitution and ${jkEx.gapCols} gap positions. One student reports ${M.fix(jkEx.pct, 1)} % similarity and another ${M.fix(jkCt.pct, 1)} %. (a) Show how each value was obtained. (2 marks) (b) Explain why the method must be stated when percentages are compared between studies. (1 mark)`, scheme: [{ point: `(a) ${jkEx.identical} ÷ ${jkEx.compared} × 100 = ${M.fix(jkEx.pct, 1)} %: gap positions excluded from the positions compared`, marks: 1 }, { point: `(a) ${jkEx.identical} ÷ ${jkEx.length} × 100 = ${M.fix(jkCt.pct, 1)} %: each gap position counted as a difference`, marks: 1 }, { point: "(b) Different conventions give different values from the same data, so values can be compared only if calculated the same way", marks: 1 }], model: `(a) The first student excluded the ${jkEx.gapCols} gap positions, comparing ${jkEx.compared} positions: ${jkEx.identical} ÷ ${jkEx.compared} × 100 = ${M.fix(jkEx.pct, 1)} %. The second counted each gap position as a difference, keeping all ${jkEx.length}: ${jkEx.identical} ÷ ${jkEx.length} × 100 = ${M.fix(jkCt.pct, 1)} %. (b) The two conventions give different percentages from identical data, so a difference between studies could reflect method rather than biology.`, commonErrors: "Treating the gap as one difference in one calculation and three in another without saying so." },
      { id: `q-${R}-s4`, ref: R, stmts: S(1), type: "short", marks: 3, stem: "A small, isolated population of a lizard has two alleles of a gene at frequencies 0.9 and 0.1. A large mainland population of the same species has five alleles at frequencies between 0.1 and 0.3. (a) Which population has greater genetic diversity for this gene? Explain. (2 marks) (b) Suggest why studying one gene may not represent the genetic diversity of the whole population. (1 mark)", scheme: [{ point: "(a) The mainland population", marks: 1 }, { point: "(a) More alleles, and more evenly represented (no single allele dominating)", marks: 1 }, { point: "(b) Other genes may show different patterns / the population may be diverse in other genes; several genes should be studied", marks: 1 }], model: "(a) The mainland population: it carries five alleles rather than two, and their frequencies are more even, whereas in the island population one allele makes up 90 % of copies. (b) Different genes can show different amounts of variation, so one gene gives only part of the picture; several genes, or the genome, should be compared.", commonErrors: "Judging diversity by population size alone." },
      { id: `q-${R}-s5`, ref: R, stmts: S(2), type: "short", marks: 3, stem: "A newspaper states that 'species X and species Y share 96 % of their DNA, so they split from each other twice as recently as species X and species Z, which share 92 %'. Evaluate this claim. (3 marks)", scheme: [{ point: "The data support X being more closely related to Y than to Z (more similar, more recent common ancestor suggested)", marks: 1 }, { point: "But percentage similarity is not an exact or proportional measure of time: rates of change differ between genes and lineages / changes can recur", marks: 1 }, { point: "And the value depends on which regions were compared, the alignment and gap convention, and the individuals sampled", marks: 1 }], model: "The higher similarity of X and Y suggests that they share a more recent common ancestor than X and Z, so that part is reasonable. However, 'twice as recently' assumes that differences build up at a constant, known rate, which is not true in general: different genes and lineages change at different rates and a position can change more than once. The percentages also depend on which regions were compared and how they were aligned, so they are evidence of relationship, not a clock.", commonErrors: "Accepting the doubling argument because 8 % is twice 4 %." },
      { id: `q-${R}-s6`, ref: R, stmts: S(2), type: "short", marks: 2, stem: `A coding region of species S and T is ${M.fix(r1.pct, 1)} % similar, but a non-coding region of the same two species is ${M.fix(r2.pct, 1)} % similar. Suggest an explanation. (2 marks)`, scheme: [{ point: "Changes in an essential coding region are likely to alter the protein and be harmful, so few persist", marks: 1 }, { point: "Changes in non-coding DNA often have little effect, so more accumulate", marks: 1 }], model: "A base change in an essential coding region is likely to change the protein and reduce the organism's chance of surviving and reproducing, so few such changes persist over generations. Many changes in non-coding DNA have little effect, so more of them accumulate, giving a lower similarity for the same pair of species.", commonErrors: "Saying non-coding DNA mutates because it is not used, without linking to whether changes persist." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2), type: "extended", marks: 6, stem: "Extended response. Scientists want to find out whether a population of gazelles in one desert reserve is closely related to a population in another reserve, and to two other gazelle species. Describe how genetic diversity could be measured and how the results could be interpreted, including the limitations of the methods. (6 marks)", scheme: [{ point: "Compare the base sequence of the same gene(s) / regions of DNA (or mRNA, with the coding strand) from several individuals of each population and species", marks: 1 }, { point: "Compare the frequencies of specific alleles / base sequences in the two populations (within-species diversity)", marks: 1 }, { point: "Compare the amino-acid sequence of the same protein(s)", marks: 1 }, { point: "Align sequences (same strand and direction) and calculate percentage similarity or number of differences", marks: 1 }, { point: "Greater similarity / fewer differences suggests closer relationship / more recent common ancestor", marks: 1 }, { point: "Limitation: degenerate code (proteins may hide DNA differences) / depends on region and gap convention / not an exact measure of divergence time / need several genes and individuals", marks: 1 }], levels: "Level 3 (5–6): at least two measures described with how to compare them, a clear interpretation in terms of relationships, and at least one well-explained limitation. Level 2 (3–4): measures named and interpretation given, limited method or limitation. Level 1 (1–2): measures listed with little interpretation.", model: "Samples would be taken from several individuals in each reserve and from each of the two other species, so that variation within each group is represented. The scientists could sequence the same genes or regions of DNA in every sample (or compare mRNA with the coding strand), check that all sequences are on the same strand and in the same direction, align them with gaps where necessary, and calculate the number of differences or the percentage similarity for each pair. Within the species, they could compare the frequencies of particular alleles or base sequences in the two reserve populations: similar frequencies suggest the populations are genetically similar, and a population with fewer alleles or one dominant allele has lower genetic diversity. They could also compare the amino-acid sequences of the same proteins. Pairs with more similar sequences are suggested to share a more recent common ancestor. However, because the genetic code is degenerate, protein comparisons can miss DNA differences; the percentage depends on which region is compared and on the gap convention; and similarity is not an exact measure of time since divergence, so several genes should be compared and the conclusions described as suggested relationships.", commonErrors: "Describing only one measure; claiming that similarity proves ancestry; comparing a single individual of each group." },
    ],
  };
})();
